syntax:
Type { value1, value2, ..., valueN } // for aggregate or array initialization
// or
Type variable = { value1, value2, ..., valueN } // copy-list-initialization

// For class types with constructors, initializer lists can invoke constructors:
ClassName obj = { arg1, arg2 }; // invokes constructor with matching parameters

code_example:
#include <iostream>
#include <array>

struct Point {
    int x;
    int y;
};

int main() {
    // Aggregate initialization with initializer list
    Point p1 = {10, 20};
    // Array initialization with initializer list
    int arr[4] = { 'a', 's', 'd', 'f' };
    // Partial initialization; remaining members are value-initialized
    std::array<int, 4> arr2 = {1, 2};
    // Default initialization with empty braces
    Point p2 = {};

    std::cout << "Point p1: (" << p1.x << ", " << p1.y << ")\n";
    std::cout << "Array arr: [" << arr[0] << ", " << arr[1] << ", " << arr[2] << ", " << arr[3] << "]\n";
    std::cout << "Point p2: (" << p2.x << ", " << p2.y << ")\n";
    return 0;
}
